// Helper function to get questions for a lab, with fallback to generic questions
export function getQuestionsForLab(labId: string): TestQuestion[] {
  // Try exact match
  if (LAB_TEST_QUESTIONS[labId]) {
    return LAB_TEST_QUESTIONS[labId];
  }

  // Try prefix-based fallback
  const lower = labId.toLowerCase();
  if (lower.startsWith('cn')) return LAB_TEST_QUESTIONS['cn-exp-1'];
  if (lower.startsWith('dsa') || lower.startsWith('data')) return LAB_TEST_QUESTIONS['dsa-exp-1'];
  if (lower.startsWith('dbms')) return LAB_TEST_QUESTIONS['dbms-exp-1'];
  if (lower.startsWith('oops') || lower.startsWith('java')) return LAB_TEST_QUESTIONS['oops-exp-1'];
  if (lower.startsWith('dld') || lower.startsWith('digital')) return LAB_TEST_QUESTIONS['dld-exp-1'];
  if (lower.startsWith('os')) return LAB_TEST_QUESTIONS['os-exp-1'];
  if (lower.startsWith('mpmc') || lower.startsWith('micro')) return LAB_TEST_QUESTIONS['mpmc-exp-1'];
  if (lower.startsWith('daa')) return LAB_TEST_QUESTIONS['daa-exp-1'];

  // Return empty — LabTest will handle this gracefully
  return [];
}

// Shuffle array using Fisher-Yates for randomized question order
export function shuffleQuestions(questions: TestQuestion[]): TestQuestion[] {
  const arr = [...questions];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}
